            new Quote { Id = "https://es.wikiquote.org/wiki/Miguel_de_Unamuno", Text = "Es en el aspecto religioso donde hay que ir a buscar lo más típico y lo más radical de un pueblo.", Author = "Miguel de Unamuno" },
